<?php defined('ABSPATH') || exit; $funnels=(new CFP_Funnels())->all(); ?>
<div class="wrap cfp-admin"><h1><?php esc_html_e('ConversionFlow Pro','conversionflow-pro'); ?></h1><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cfp-card"><input type="hidden" name="action" value="cfp_create_funnel"><?php wp_nonce_field('cfp_create_funnel'); ?><h2><?php esc_html_e('Create Funnel','conversionflow-pro'); ?></h2><input name="funnel_name" class="regular-text" placeholder="<?php esc_attr_e('Funnel Name','conversionflow-pro'); ?>"> <select name="funnel_type"><option value="sales">Sales</option><option value="lead">Lead Generation</option><option value="webinar">Webinar</option></select><p><?php foreach(CFP_Steps::labels() as $key=>$label): ?><label><input type="checkbox" name="steps[]" value="<?php echo esc_attr($key); ?>" <?php checked(in_array($key,array('landing','checkout','thank_you'),true)); ?>> <?php echo esc_html($label); ?></label><br><?php endforeach; ?></p><button class="button button-primary"><?php esc_html_e('Create Funnel','conversionflow-pro'); ?></button></form><table class="widefat striped"><thead><tr><th>Funnel name</th><th>Funnel type</th><th>Steps count</th><th>Status</th><th>Visitors</th><th>Conversions</th><th>Revenue</th><th>Order bump revenue</th><th>Upsell revenue</th><th>Created date</th><th>Actions</th></tr></thead><tbody><?php foreach($funnels as $f): ?><tr><td><?php echo esc_html($f['name']); ?></td><td><?php echo esc_html($f['type']); ?></td><td><?php echo esc_html((new CFP_Analytics())->steps_count((int)$f['id'])); ?></td><td><?php echo esc_html($f['status']); ?></td><td><?php echo esc_html((new CFP_Analytics())->metric((int)$f['id'],'visit')); ?></td><td><?php echo esc_html((new CFP_Analytics())->metric((int)$f['id'],'order_paid')); ?></td><td><?php echo wc_price((new CFP_Analytics())->revenue((int)$f['id'],'order_paid')); ?></td><td><?php echo wc_price((new CFP_Analytics())->revenue((int)$f['id'],'bump_accepted')); ?></td><td><?php echo wc_price((new CFP_Analytics())->revenue((int)$f['id'],'upsell_accepted')); ?></td><td><?php echo esc_html($f['created_at']); ?></td><td><a href="#">Edit funnel</a> | <a href="#">Preview</a> | <a href="#">Duplicate</a> | <a href="#">Export</a> | <a href="#">Archive</a> | <a href="#">Delete</a></td></tr><?php endforeach; ?></tbody></table></div>
